<script>
(() => {
 const modal=document.getElementById('seoHelpModal'); if(!modal) return;
 const title=document.getElementById('seoHelpTitle'),kicker=document.getElementById('seoHelpKicker'),intro=document.getElementById('seoHelpIntro'),steps=document.getElementById('seoHelpSteps'),tip=document.getElementById('seoHelpTip'),official=document.getElementById('seoHelpOfficial');
 const guides={
 google_verification:{kicker:'GOOGLE SEARCH CONSOLE',title:'Google Search Console verification',intro:'Verify that you own fuelfreepowerplant.com using Google’s HTML tag method.',url:'https://search.google.com/search-console',steps:['Open Google Search Console and sign in with the Google account that should manage this website.','Click the property selector, choose Add property, then add your website/domain.','Choose the HTML tag verification method when Google offers verification methods.','Copy only the value inside content="..." from the google-site-verification meta tag. Do not copy the full HTML tag.','Return here, paste the value into Google Search Console verification, then click Save SEO settings.','Go back to Search Console and click Verify. If verification fails, confirm the value was copied exactly.'],tip:'The verification value is inserted into the public website head so Google can confirm ownership.'},
 bing_verification:{kicker:'BING WEBMASTER',title:'Bing Webmaster verification',intro:'Add your website to Bing Webmaster Tools and complete HTML meta-tag verification.',url:'https://www.bing.com/webmasters/',steps:['Open Bing Webmaster Tools and sign in with your Microsoft account.','Add fuelfreepowerplant.com as a site if it is not already listed.','Open the verification options and choose the HTML meta tag method.','Copy the verification content value supplied by Bing; copy the value, not the whole meta tag.','Return here, paste it into Bing Webmaster verification, and click Save SEO settings.','Return to Bing Webmaster Tools and complete verification.'],tip:'The value stored here is public because it is rendered into the website head for ownership verification.'},
 meta_verification:{kicker:'META BUSINESS',title:'Meta domain verification',intro:'Verify the website domain in Meta Business settings when your organization uses Meta/Facebook business assets.',url:'https://business.facebook.com/',steps:['Open Meta Business and sign in with the business account that owns the domain.','Open Business Settings and find Domains under your business assets/settings.','Add or select fuelfreepowerplant.com and choose the meta-tag verification method when available.','Copy only the verification value provided by Meta.','Return here, paste it into Meta domain verification, and click Save SEO settings.','Return to Meta Business and complete the verification step.'],tip:'If Meta presents DNS or HTML-file verification instead, follow that method; this field is specifically for the meta-tag content value.'},
 ga4_measurement_id:{kicker:'GOOGLE ANALYTICS 4',title:'GA4 Measurement ID',intro:'Connect this website to a GA4 web data stream using its public Measurement ID.',url:'https://analytics.google.com/',steps:['Open Google Analytics and select the correct account and GA4 property.','Go to Admin, then Data collection and modification → Data streams.','Open the Web data stream for fuelfreepowerplant.com.','In Stream details, find Measurement ID. It starts with G-.','Copy the complete ID, for example G-XXXXXXXXXX, and paste it here.','Click Save SEO settings, then use the GA4 Realtime report to confirm traffic is arriving.'],tip:'The Measurement ID identifies the GA4 web data stream and is normally shown in the form G-XXXXXXXXXX.'},
 indexnow_key:{kicker:'INDEXNOW',title:'IndexNow API key',intro:'Create a website-specific IndexNow key and publish it through this system for verification.',url:'https://www.indexnow.org/documentation',steps:['Open the IndexNow documentation and generate or choose a unique key for this website.','Return here and paste the key into IndexNow API key. Use only letters, numbers, hyphens or underscores.','Click Save SEO settings.','This website will expose the key at /indexnow/{key}.txt so search engines can verify ownership of the key.','Use the exact key and website URL when submitting supported URLs to an IndexNow endpoint.','If the provider reports a key error, first open your public /indexnow/{key}.txt URL and confirm it returns the exact key text.'],tip:'The public key file must return the exact same key that you saved here.'}
 };
 const open=(topic)=>{const guide=guides[topic];if(!guide)return;kicker.textContent=guide.kicker;title.textContent=guide.title;intro.textContent=guide.intro;steps.innerHTML=guide.steps.map(step=>`<li>${step}</li>`).join('');tip.textContent=guide.tip;official.href=guide.url;modal.classList.add('is-open');modal.setAttribute('aria-hidden','false');document.body.classList.add('seo-modal-open');modal.querySelector('.seo-modal-close')?.focus()};
 const close=()=>{modal.classList.remove('is-open');modal.setAttribute('aria-hidden','true');document.body.classList.remove('seo-modal-open')};
 document.querySelectorAll('[data-help-topic]').forEach(button=>button.addEventListener('click',()=>open(button.dataset.helpTopic)));
 modal.querySelectorAll('[data-help-close]').forEach(el=>el.addEventListener('click',close));
 document.addEventListener('keydown',event=>{if(event.key==='Escape'&&modal.classList.contains('is-open'))close()});
})();
</script>
@endpush